head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDFIS00200_17.gfm";
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자
scwin.vArray = "";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    // 결산일자 조회

	//----W-Craft WebSquare 변환 확인: fn_SrchAcntclsDt----//
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_LstrmDebtStat.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.

	//----W-Craft WebSquare 변환 확인: fn_GetKisCd----//
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

	//----W-Craft WebSquare 변환 확인: fn_GetAcntclsDt----//
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd == "" || scwin.vAcntclsDt == "") {
        return false;
    }
    return true;
};


/**
 * 장단기차입금  조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_LstrmDebtStat);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.lstrmDebtStat" + "&outputMessageId=FIS_LSTRM_DEBT_STAT" + "&param01=" + scwin.vKisCd + "&param02=" + scwin.vArray[0].VALUE + "&param03=" + scwin.vArray[1].VALUE + "&param04=" + scwin.vArray[2].VALUE;
    dts_LstrmDebtStat.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_LstrmDebtStat.Reset();
};


/**
 * 그리드 헤더의 제목을 세팅.
 */
scwin.fn_SetGrdHeaderNm = function(pArray) {
    $c.cm.setColumnProp(grd_LstrmDebtStat, "AMT1", "Name", pArray[0].TEXT);
    $c.cm.setColumnProp(grd_LstrmDebtStat, "AMT2", "Name", pArray[1].TEXT);
    $c.cm.setColumnProp(grd_LstrmDebtStat, "AMT3", "Name", pArray[2].TEXT);
    scwin.vArray = pArray;
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dts_LstrmDebtStat.getTotalRow() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_LstrmDebtStat, "장단기차입금현황", "", "8");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_LstrmDebtStat_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_LstrmDebtStat);
    $c.stf.alert_error(dts_LstrmDebtStat);
};
scwin.dts_LstrmDebtStat_OnLoadCompleted = function(rowcount) {
    if (dts_LstrmDebtStat.errorMsg) {
        alert(dts_LstrmDebtStat.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_LstrmDebtStat);
};
